### 5.2 Database User Setup

```sql
-- Connect as superuser
psql -h postgres-cluster-rw -U postgres

-- Create application user
CREATE USER rating_app WITH PASSWORD 'secure_generated_password';
GRANT CONNECT ON DATABASE rating_service TO rating_app;

-- Switch to rating_service database
\c rating_service;

-- Grant permissions
GRANT USAGE ON SCHEMA public TO rating_app;
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA public TO rating_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO rating_app;

-- Create read-only user for analytics
CREATE USER rating_readonly WITH PASSWORD 'readonly_password';
GRANT CONNECT ON DATABASE rating_service TO rating_readonly;
GRANT USAGE ON SCHEMA public TO rating_readonly;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO rating_readonly;
```

